import React from 'react';
import clsx from 'clsx';

interface ProgressBarProps {
  progress: number;
  className?: string;
  isSelected?: boolean;
  isInProgress?: boolean;
  completedPercent?: number;
  supersededPercent?: number;
}

const ProgressBar: React.FC<ProgressBarProps> = ({
  progress,
  className,
  isInProgress,
  completedPercent,
  supersededPercent = 0
}) => {
  const isComplete = progress >= 100;
  const safeProgress = Math.min(100, Math.max(0, progress));
  const hasSuperseded = supersededPercent > 0;

  // If we have explicit completed/superseded percentages, use them for mixed bar
  const safeCompletedPercent = completedPercent !== undefined
    ? Math.min(100, Math.max(0, completedPercent))
    : safeProgress;
  const safeSupersededPercent = Math.min(100, Math.max(0, supersededPercent));

  return (
    <div className={clsx(
      'relative overflow-hidden h-2 rounded-full',
      isInProgress
        ? 'bg-gray-300/50 dark:bg-gray-600/50 ring-1 ring-gray-400/30 dark:ring-gray-500/30'
        : 'progress-bar',
      className
    )}>
      {/* Mixed progress bar when we have superseded tasks */}
      {hasSuperseded ? (
        <>
          {/* Orange background for superseded (full width of completed + superseded) */}
          <div
            className="absolute h-full bg-orange-500 dark:bg-orange-600 transition-all duration-300"
            style={{ width: `${safeCompletedPercent + safeSupersededPercent}%` }}
          />
          {/* Green foreground for completed */}
          <div
            className={clsx(
              'absolute h-full transition-all duration-300',
              isComplete ? 'bg-green-500 dark:bg-green-600' : 'progress-fill'
            )}
            style={{ width: `${safeCompletedPercent}%` }}
          />
        </>
      ) : (
        <div
          className={clsx(
            'h-full transition-all duration-300',
            // Always show green if 100% complete, regardless of selection
            isComplete ? 'progress-fill-complete' : 'progress-fill'
          )}
          style={{ width: `${safeProgress}%` }}
        />
      )}
      {/* Shimmer effect for completed progress bars */}
      {isComplete && (
        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-shimmer-once pointer-events-none" />
      )}
    </div>
  );
};

export default ProgressBar;