import { useState } from 'react';
import type { TelemetryEvent } from '@magic-ingredients/tiny-brain-core';
import { getStepEmoji, getStepLabel } from '../utils/step-display';

interface PhaseGroup {
  readonly phase: string;
  readonly events: TelemetryEvent[];
  readonly duration_ms?: number;
  readonly sha?: string;
}

function inferPhaseFromEvent(event: TelemetryEvent): string {
  if (event.kind === 'pipeline.decision' || event.kind === 'persist.review_written') {
    return `review:${event.gate}`;
  }
  if (event.kind === 'commit.tracked') {
    if (event.type === 'test') return 'red';
    if (event.type === 'feat' || event.type === 'fix') return 'green';
    if (event.type === 'refactor') return 'refactor:post-review';
  }
  return 'unknown';
}

function groupByPhase(events: TelemetryEvent[]): PhaseGroup[] {
  const groups: PhaseGroup[] = [];
  let current: PhaseGroup | null = null;

  for (const event of events) {
    if (event.kind === 'phase.entered') {
      current = { phase: event.phase, events: [], duration_ms: undefined, sha: undefined };
      groups.push(current);
    }

    if (current) {
      // If a commit.tracked event doesn't belong to the current phase,
      // place it in the previous group (or create one). Handles events
      // written before the ordering fix where commit.tracked arrived
      // after phase.entered for the next phase.
      if (event.kind === 'commit.tracked') {
        const inferred = inferPhaseFromEvent(event);
        const belongsHere = inferred === current.phase
          || (inferred.startsWith('refactor:') && current.phase.startsWith('refactor:'));
        if (!belongsHere) {
          const prev = groups.length >= 2 ? groups[groups.length - 2] : null;
          if (prev && prev.phase === inferred) {
            prev.events.push(event);
          } else {
            const newGroup: PhaseGroup = { phase: inferred, events: [event] };
            groups.splice(groups.length - 1, 0, newGroup);
          }
          continue;
        }
      }

      current.events.push(event);
      if (event.kind === 'phase.completed') {
        current = { ...current, duration_ms: event.duration_ms, sha: event.sha };
        groups[groups.length - 1] = current;
      }
    } else {
      const inferred = inferPhaseFromEvent(event);
      const lastGroup = groups[groups.length - 1];
      if (lastGroup && lastGroup.phase === inferred) {
        lastGroup.events.push(event);
      } else {
        groups.push({ phase: inferred, events: [event] });
      }
    }
  }

  return groups;
}

/**
 * Compute total task wall-clock for the ✅ Complete header.
 *
 * The complete phase isn't a real worker phase — its duration is the
 * elapsed time from the earliest phase.entered to the task.completed
 * event, including idle gaps between phases. Without a task.completed
 * the total is unknown, so we leave the Complete header silent.
 *
 * Earliest is computed by timestamp (not first-in-array) so re-ordered
 * telemetry — say, a reconciliation backfill — doesn't anchor the
 * total to whichever phase.entered happens to be first in the slice.
 */
function withCompleteTotal(
  groups: readonly PhaseGroup[],
  events: readonly TelemetryEvent[],
): PhaseGroup[] {
  const completed = events.find((e) => e.kind === 'task.completed');
  const phaseStarts = events.filter((e) => e.kind === 'phase.entered');
  if (!completed || phaseStarts.length === 0) return [...groups];

  const earliestStartMs = Math.min(
    ...phaseStarts.map((e) => new Date(e.ts).getTime()),
  );
  const totalMs = new Date(completed.ts).getTime() - earliestStartMs;
  if (totalMs < 0) return [...groups];

  return groups.map((g) => (g.phase === 'complete' ? { ...g, duration_ms: totalMs } : g));
}

function formatDuration(ms: number): string {
  // Sub-second renders as "<1 sec" so a quick phase doesn't print a
  // misleading "0 sec". Above one second we go verbose: sec / min sec /
  // hr min. Hour-scale collapses seconds — at that timescale they're
  // not informative.
  if (ms < 1000) return '<1 sec';
  const totalSeconds = Math.floor(ms / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  if (hours > 0) {
    return `${hours} hr${minutes > 0 ? ` ${minutes} min` : ''}`;
  }
  if (minutes > 0) {
    return `${minutes} min${seconds > 0 ? ` ${seconds} sec` : ''}`;
  }
  return `${seconds} sec`;
}

function phaseLabel(phase: string): string {
  if (phase.startsWith('review:')) {
    const gate = phase.slice('review:'.length);
    return `${getStepEmoji(gate)} ${getStepLabel(gate)}`;
  }
  if (phase.startsWith('refactor:')) return `${getStepEmoji('refactor')} ${getStepLabel('refactor')}`;
  if (phase === 'unknown') return '❓';
  return `${getStepEmoji(phase)} ${getStepLabel(phase)}`;
}

const SOURCE_STYLES: Record<string, string> = {
  agent: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  watcher: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
  reconciliation: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300',
};

function eventSummary(event: TelemetryEvent): string {
  switch (event.kind) {
    case 'phase.entered': return `Entered ${event.phase}`;
    case 'phase.completed': return `Completed ${event.phase}`;
    case 'commit.tracked': return `${event.type} commit ${event.sha.substring(0, 7)}`;
    case 'persist.review_written': return `Review written`;
    case 'pipeline.decision': return `Decision`;
    case 'pipeline.advance.rejected':
      return `Rejected 2nd commit ${event.rejectedSha.substring(0, 7)} (already complete)`;
    case 'inbox.reminder_written': return `Reminder written (${event.reminder_id})`;
    case 'inbox.reminder_drained': return `Reminder drained (${event.reminder_id})`;
    case 'task.completed': return `Task completed (${event.final_sha.substring(0, 7)})`;
  }
}

const DECISION_PILL_STYLES: Record<string, string> = {
  clean: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
  dirty: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300',
};

function verdictLabel(verdict: string): string {
  if (verdict === 'dirty') return 'Needs refactor';
  if (verdict === 'clean') return 'Passed';
  return verdict;
}

function EventRow({ event, index, expanded, onToggle }: {
  event: TelemetryEvent;
  index: number;
  expanded: boolean;
  onToggle: () => void;
}) {
  const isNoop = event.kind === 'pipeline.decision' && event.was_noop;

  return (
    <div
      data-testid={`event-row-${index}`}
      className={`py-1.5 pl-6 border-l-2 border-gray-200 dark:border-gray-700 ${isNoop ? 'opacity-50' : ''}`}
    >
      <div className="flex items-center gap-2 text-sm">
        <span className="text-xs text-muted-foreground font-mono whitespace-nowrap">
          {new Date(event.ts).toLocaleTimeString()}
        </span>
        <span className="text-sm flex-1 truncate">
          {eventSummary(event)}
        </span>
        {event.kind === 'pipeline.decision' && (
          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${DECISION_PILL_STYLES[event.decision] ?? ''}`}>
            {verdictLabel(event.decision)}
          </span>
        )}
        {event.kind === 'persist.review_written' && event.verdict && (
          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${DECISION_PILL_STYLES[event.verdict] ?? ''}`}>
            {verdictLabel(event.verdict)}
          </span>
        )}
        {event.kind === 'pipeline.decision' && (
          <span className={`text-xs px-1.5 py-0.5 rounded-full font-medium ${SOURCE_STYLES[event.source] ?? ''}`}>
            {event.source}
          </span>
        )}
        <button
          onClick={onToggle}
          aria-label="details"
          className="text-xs text-muted-foreground hover:text-foreground px-1"
        >
          {expanded ? '▲' : '▼'}
        </button>
      </div>
      {expanded && (
        <pre
          data-testid={`event-detail-${index}`}
          className="mt-1 ml-4 p-2 bg-gray-100 dark:bg-gray-800 rounded text-xs overflow-auto max-h-40"
        >
          {JSON.stringify(event, null, 2)}
        </pre>
      )}
    </div>
  );
}

function PhaseSection({ group }: { group: PhaseGroup }) {
  return (
    <div className="mb-4">
      <div data-testid="phase-header" className="flex items-center gap-2 mb-2 text-sm font-semibold">
        <span>{phaseLabel(group.phase)}</span>
        {group.duration_ms != null && (
          <span className="text-xs text-muted-foreground font-normal">
            {formatDuration(group.duration_ms)}
          </span>
        )}
        {group.sha && (
          <span className="text-xs font-mono text-muted-foreground font-normal">
            {group.sha.substring(0, 7)}
          </span>
        )}
      </div>
    </div>
  );
}

export function TaskTimeline({ events }: { events: TelemetryEvent[] }) {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(null);

  if (events.length === 0) {
    return (
      <div className="text-sm text-muted-foreground text-center py-8">
        No telemetry events yet for this task
      </div>
    );
  }

  const completedIdx = events.findIndex(e => e.kind === 'task.completed');
  const pipelineEvents = completedIdx >= 0 ? events.slice(0, completedIdx + 1) : events;
  const postCompletionEvents = completedIdx >= 0 ? events.slice(completedIdx + 1) : [];
  const rawGroups = groupByPhase(pipelineEvents);
  const groups = withCompleteTotal(rawGroups, pipelineEvents);

  let globalIndex = 0;

  return (
    <div className="space-y-2">
      {groups.map((group, gi) => {
        const startIdx = globalIndex;
        const rows = group.events.map((event, ei) => {
          const idx = startIdx + ei;
          return (
            <EventRow
              key={idx}
              event={event}
              index={idx}
              expanded={expandedIndex === idx}
              onToggle={() => setExpandedIndex(expandedIndex === idx ? null : idx)}
            />
          );
        });
        globalIndex += group.events.length;
        return (
          <div key={gi}>
            <PhaseSection group={group} />
            {rows}
          </div>
        );
      })}
      {postCompletionEvents.length > 0 && (
        <div data-testid="post-completion-section" className="mt-4 pt-4 border-t border-dashed border-gray-300 dark:border-gray-600">
          <div className="text-xs text-muted-foreground font-semibold mb-2">Post-completion activity</div>
          {postCompletionEvents.map((event, ei) => {
            const idx = globalIndex + ei;
            return (
              <EventRow
                key={idx}
                event={event}
                index={idx}
                expanded={expandedIndex === idx}
                onToggle={() => setExpandedIndex(expandedIndex === idx ? null : idx)}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}
