import type { ConfigHealth } from '../types';

/**
 * Analyzes a ConfigHealth object and returns human-readable issue descriptions.
 * Returns an empty array when the config is healthy.
 */
export const getConfigIssues = (health: ConfigHealth): readonly string[] => {
  if (health.isGitRepo === false) {
    return ['Not a git repository'];
  }

  const issues: string[] = [];

  // Hooks: check for uninstalled hooks
  const hooks = [health.hooks.preCommit, health.hooks.commitMsg, health.hooks.postCommit];
  const uninstalledCount = hooks.filter((h) => !h.installed).length;

  if (uninstalledCount === 3) {
    issues.push('Git hooks not installed');
  } else if (uninstalledCount > 0) {
    issues.push(`${uninstalledCount} git hook${uninstalledCount === 1 ? '' : 's'} not installed`);
  }

  // Hooks: check for installed-but-unsigned hooks
  const unsignedCount = hooks.filter((h) => h.installed && !h.signed).length;
  if (unsignedCount > 0) {
    issues.push(`${unsignedCount} git hook${unsignedCount === 1 ? '' : 's'} not signed`);
  }

  // CLAUDE.md (contextBlock)
  if (!health.contextBlock.present) {
    issues.push('CLAUDE.md not found');
  } else {
    if (!health.contextBlock.upToDate) {
      issues.push('CLAUDE.md outdated');
    }
    if (health.contextBlock.missingSections.length > 0) {
      const count = health.contextBlock.missingSections.length;
      issues.push(`${count} CLAUDE.md section${count === 1 ? '' : 's'} missing`);
    }
  }

  // Permissions
  if (!health.permissions.present) {
    issues.push('Permissions file missing');
  } else if (health.permissions.missing.length > 0) {
    const count = health.permissions.missing.length;
    issues.push(`${count} permission${count === 1 ? '' : 's'} missing`);
  }

  // Directories
  if (health.directories.missing.length > 0) {
    const count = health.directories.missing.length;
    issues.push(`${count} director${count === 1 ? 'y' : 'ies'} missing`);
  }

  return issues;
};
