import React, { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import { Circle, Play, CheckCircle2, FastForward, GitBranch } from 'lucide-react';
import type { TaskRowTask, TddPhase } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { deriveTddPhase } from '../utils/tdd-phases';
import TddPhasePipeline from './TddPhasePipeline';
import CommitDetailsPopover from './CommitDetailsPopover';
import AdversarialReviewPopover from './AdversarialReviewPopover';

interface TaskRowProps {
  task: TaskRowTask;
  repoId: string;
  onClick?: () => void;
  reviewPipeline?: PipelineStep[];
}

const phaseLabels: Record<Exclude<TddPhase, 'complete'>, string> = {
  red: 'Writing failing tests (TDD red phase)..',
  green: 'Writing an implementation (TDD green phase)..',
  adversarial: "Reviewing what's been done..",
  'adversarial-refactor': 'Making things better (TDD refactor phase)..',
  mutation: 'Spawning mutants..',
  'mutation-refactor': 'Making things better post mutation (TDD refactor phase)..',
};

const statusConfig: Record<
  TaskRowTask['status'],
  { icon: React.FC<{ className?: string }>; title: string; iconClass: string }
> = {
  not_started: { icon: Circle, title: 'Not started', iconClass: 'text-muted-foreground' },
  in_progress: { icon: Play, title: 'In progress', iconClass: 'text-blue-500' },
  completed: { icon: CheckCircle2, title: 'Completed', iconClass: 'text-green-500' },
  superseded: { icon: FastForward, title: 'Superseded', iconClass: 'text-orange-500' },
};

const phaseToCommitType = (phase: TddPhase): 'test' | 'feat' | 'refactor' => {
  switch (phase) {
    case 'red': return 'test';
    case 'green': return 'feat';
    default: return 'refactor';
  }
};

const TaskRow: React.FC<TaskRowProps> = ({ task, repoId, onClick, reviewPipeline }) => {
  const { icon: Icon, title, iconClass } = statusConfig[task.status] ?? statusConfig.not_started;
  const [selectedCommit, setSelectedCommit] = useState<{ sha: string; type: 'test' | 'feat' | 'refactor' } | null>(null);
  const [selectedReview, setSelectedReview] = useState<{ commitSha: string; reviewType: string } | null>(null);

  const handlePhaseClick = (phase: TddPhase, commitSha: string): void => {
    // Generic pipeline phases: review:{type}
    if (phase.startsWith('review:')) {
      setSelectedReview({ commitSha, reviewType: phase.slice(7) });
    // Legacy hardcoded phases
    } else if (phase === 'adversarial') {
      setSelectedReview({ commitSha, reviewType: 'adversarial' });
    } else if (phase === 'mutation') {
      setSelectedReview({ commitSha, reviewType: 'mutation' });
    } else {
      setSelectedCommit({ sha: commitSha, type: phaseToCommitType(phase) });
    }
  };

  const hasAnyPhaseCommit = !!(task.testCommitSha || task.commitSha);
  const enablePhaseClick = repoId && hasAnyPhaseCommit ? handlePhaseClick : undefined;

  const isCompleted = task.status === 'completed';
  const bgClass = isCompleted
    ? 'bg-green-50 dark:bg-green-950/30 border-green-200 dark:border-green-900'
    : 'border-muted';
  const hoverClass = onClick
    ? isCompleted
      ? 'cursor-pointer hover:bg-green-100 dark:hover:bg-green-950/50'
      : 'cursor-pointer hover:bg-muted/50'
    : '';

  return (
    <div
      className={`flex items-center gap-3 py-1.5 px-2 rounded-lg border ${bgClass} ${hoverClass}`}
      role={onClick ? 'button' : undefined}
      onClick={onClick}
    >
      {/* Status icon */}
      <div className="flex-shrink-0" title={title}>
        <Icon className={`h-5 w-5 ${iconClass}`} />
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <div className={`text-sm ${task.status === 'superseded' ? 'line-through text-muted-foreground' : ''}`}>
          <ReactMarkdown components={{ p: ({ children }) => <span>{children}</span> }}>
            {task.description}
          </ReactMarkdown>
        </div>

        {/* Second row — always visible */}
        {(() => {
          if (task.status === 'superseded') {
            return <p className="text-xs text-orange-600 mt-0.5">{task.note ?? 'Superseded'}</p>;
          }
          // Check for active TDD cycle — phase label takes priority over "Completed"
          const derived = deriveTddPhase(task, reviewPipeline);
          if (derived !== 'complete' && derived !== 'red') {
            let label: string | undefined;
            if (derived.startsWith('review:')) {
              const type = derived.slice(7);
              const step = reviewPipeline?.find(s => s.type === type);
              label = step ? `${step.label} review in progress..` : `${type} review in progress..`;
            } else if (derived.startsWith('refactor:')) {
              const type = derived.slice(9);
              const step = reviewPipeline?.find(s => s.type === type);
              label = step ? `Refactoring after ${step.label} review..` : `Refactoring after ${type} review..`;
            } else {
              label = phaseLabels[derived as keyof typeof phaseLabels];
            }
            if (label) {
              return <p className="text-xs text-muted-foreground italic mt-0.5">{label}</p>;
            }
          }
          // Red phase also gets a label when task has started TDD
          if (derived === 'red' && task.redStartedAt) {
            return <p className="text-xs text-muted-foreground italic mt-0.5">{phaseLabels.red}</p>;
          }
          if (task.status === 'completed') {
            return task.completedAt
              ? <p className="text-xs text-muted-foreground mt-0.5">Completed at {new Date(task.completedAt).toLocaleDateString()}</p>
              : <p className="text-xs text-muted-foreground mt-0.5">Completed</p>;
          }
          return <p className="text-xs text-muted-foreground mt-0.5">Not started</p>;
        })()}
      </div>

      {/* Worktree badge */}
      {task.worktree && (
        <span
          data-testid="worktree-badge"
          className="flex-shrink-0 inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-xs bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-300"
        >
          <GitBranch className="h-3 w-3" />
          {task.worktree.name}
        </span>
      )}

      {/* TddPhasePipeline — show when TDD activity exists */}
      {(() => {
        const hasTddActivity = !!(task.redStartedAt || task.testCommitSha);
        return task.status !== 'superseded' && (task.status !== 'not_started' || hasTddActivity);
      })() && (
        <div className="flex-shrink-0" onClick={(e) => e.stopPropagation()}>
          <TddPhasePipeline
            task={task}
            repoId={repoId}
            reviewPipeline={reviewPipeline}
            onPhaseClick={enablePhaseClick}
          />
        </div>
      )}

      <CommitDetailsPopover
        commitSha={selectedCommit?.sha ?? ''}
        commitType={selectedCommit?.type ?? 'test'}
        repoId={repoId}
        open={selectedCommit !== null}
        onOpenChange={(open) => { if (!open) setSelectedCommit(null); }}
      />

      <AdversarialReviewPopover
        commitSha={selectedReview?.commitSha ?? ''}
        repoId={repoId}
        reviewType={selectedReview?.reviewType ?? 'adversarial'}
        open={selectedReview !== null}
        onOpenChange={(open) => { if (!open) setSelectedReview(null); }}
      />
    </div>
  );
};

export default TaskRow;
