import React, { useState } from 'react';
import { GripVertical, Plus, X } from 'lucide-react';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';
import { Popover, PopoverTrigger, PopoverContent } from './ui/popover';
import {
  DndContext,
  DragOverlay,
  pointerWithin,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  useDroppable,
  type DragEndEvent,
  type DragStartEvent,
  type CollisionDetection,
} from '@dnd-kit/core';
import {
  SortableContext,
  horizontalListSortingStrategy,
  useSortable,
  arrayMove,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';

interface PipelineEditorProps {
  /** Full pipeline including hook steps and review steps */
  pipeline: PipelineStep[];
  /** All available capability types (active + inactive shown) */
  available: PipelineStep[];
  onSave: (pipeline: PipelineStep[]) => void;
  saving?: boolean;
  showFixedPhases?: boolean;
  /** Show items as parallel (no ordering, no drag) instead of sequential */
  parallel?: boolean;
  /** Hook name for this pipeline (e.g. 'pre-commit'). Enables hook drop zone when set. */
  hookName?: 'pre-commit' | 'pre-push';
}

const FIXED_PHASES = [
  { emoji: '\u{1F534}', label: 'Red TDD Phase', hue: 25 },
  { emoji: '\u{1F7E2}', label: 'Green TDD Phase', hue: 145 },
];

function phaseColors(hue: number, isDark: boolean) {
  return {
    bg: isDark ? `oklch(0.3 0.06 ${hue})` : `oklch(0.95 0.04 ${hue})`,
    border: isDark ? `oklch(0.45 0.1 ${hue})` : `oklch(0.8 0.08 ${hue})`,
    text: isDark ? `oklch(0.8 0.08 ${hue})` : `oklch(0.35 0.12 ${hue})`,
  };
}

/** Classify a step as static based on analyzer field or analyzer-agent usage */
function isStaticAnalyser(step: PipelineStep, staticTypes?: Set<string>): boolean {
  return !!step.analyzer || step.agent === 'tiny-brain:analyzer-agent' || (staticTypes?.has(step.type) ?? false);
}

/** Step type color schemes */
const STEP_COLORS = {
  static: {
    border: 'border-gray-300 dark:border-gray-500',
    bg: 'bg-gray-100 dark:bg-gray-600',
    text: 'text-gray-700 dark:text-gray-200',
  },
  agentic: {
    border: 'border-purple-300 dark:border-purple-500',
    bg: 'bg-purple-50 dark:bg-purple-900/40',
    text: 'text-purple-800 dark:text-purple-200',
  },
} as const;

// --- Sortable item for active pipeline entries ---
const TollgateBadge: React.FC<{ maxAttempts: number }> = ({ maxAttempts }) => (
  <span
    data-testid="tollgate-badge"
    className="absolute bottom-0.5 right-0.5 text-[9px] font-bold leading-none px-1 py-0.5 rounded bg-amber-200 text-amber-800 dark:bg-amber-800 dark:text-amber-200"
  >
    {maxAttempts}x
  </span>
);

const SortableItem: React.FC<{
  id: string;
  label: string;
  emoji: string;
  saving?: boolean;
  isStatic?: boolean;
  isTollgate?: boolean;
  maxAttempts?: number;
  onRemove: () => void;
  onConfigure?: () => void;
}> = ({ id, label, emoji, saving, isStatic, isTollgate, maxAttempts, onRemove, onConfigure }) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id, disabled: saving });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
    zIndex: isDragging ? 10 : 0,
  };

  return (
    <li
      ref={setNodeRef}
      role="listitem"
      data-active="true"
      data-testid={`step-card-${id}`}
      style={style}
      className={`flex flex-col items-center gap-0.5 rounded-lg border w-[104px] h-[76px] justify-center relative pt-3 pb-2 cursor-pointer ${isStatic ? `${STEP_COLORS.static.border} ${STEP_COLORS.static.bg} ${STEP_COLORS.static.text}` : `${STEP_COLORS.agentic.border} ${STEP_COLORS.agentic.bg} ${STEP_COLORS.agentic.text}`}`}
      onClick={onConfigure}
    >
      {/* Drag handle */}
      <button
        type="button"
        aria-label={`Drag to reorder ${id}`}
        className="absolute top-1 right-1 p-0.5 cursor-grab active:cursor-grabbing text-gray-400 dark:text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
        {...attributes}
        {...listeners}
      >
        <GripVertical className="h-3 w-3" />
      </button>

      {/* Remove pill */}
      <button
        type="button"
        aria-label={`Remove ${label}`}
        disabled={saving}
        onClick={(e) => { e.stopPropagation(); onRemove(); }}
        className="absolute top-1 left-1 p-0.5 rounded-full text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 transition-colors"
      >
        <X className="h-3 w-3" />
      </button>

      <span className="text-xl">{emoji}</span>
      <span className="text-xs font-medium text-center leading-tight">{label}</span>
      {isTollgate && maxAttempts != null && <TollgateBadge maxAttempts={maxAttempts} />}
    </li>
  );
};

// --- Parallel item (no drag handle) ---
const ParallelItem: React.FC<{
  id: string;
  label: string;
  emoji: string;
  saving?: boolean;
  isStatic?: boolean;
  isTollgate?: boolean;
  maxAttempts?: number;
  onRemove: () => void;
  onConfigure?: () => void;
}> = ({ id, label, emoji, saving, isStatic, isTollgate, maxAttempts, onRemove, onConfigure }) => (
  <li role="listitem" data-active="true" data-testid={`step-card-${id}`} onClick={onConfigure} className={`flex flex-col items-center gap-0.5 rounded-lg border w-[104px] h-[76px] justify-center relative pt-3 pb-2 cursor-pointer ${isStatic ? `${STEP_COLORS.static.border} ${STEP_COLORS.static.bg} ${STEP_COLORS.static.text}` : `${STEP_COLORS.agentic.border} ${STEP_COLORS.agentic.bg} ${STEP_COLORS.agentic.text}`}`}>
    {/* Remove pill */}
    <button
      type="button"
      aria-label={`Remove ${label}`}
      disabled={saving}
      onClick={(e) => { e.stopPropagation(); onRemove(); }}
      className="absolute top-1 left-1 p-0.5 rounded-full text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 transition-colors"
    >
      <X className="h-3 w-3" />
    </button>

    <span className="text-xl">{emoji}</span>
    <span className="text-xs font-medium text-center leading-tight">{label}</span>
    {isTollgate && maxAttempts != null && <TollgateBadge maxAttempts={maxAttempts} />}
  </li>
);

const ZONE_IDS = new Set(['hook-zone', 'review-zone']);

/**
 * Collision detection: pointerWithin for all targets.
 * Prefers sortable items (for reorder) over zones, but zones are valid drop targets.
 */
const zoneAwareCollision: CollisionDetection = (args) => {
  const hits = pointerWithin(args);
  if (hits.length === 0) return [];

  // Prefer sortable item hits over zone hits (for within-zone reorder)
  const sortableHits = hits.filter(c => !ZONE_IDS.has(c.id as string));
  if (sortableHits.length > 0) return sortableHits;

  // No sortable under pointer — return the zone hit (cross-zone drop)
  return hits.filter(c => ZONE_IDS.has(c.id as string));
};

/** Droppable zone for cross-zone drag */
const DroppableZone: React.FC<{ id: string; children: React.ReactNode; className?: string }> = ({ id, children, className }) => {
  const { setNodeRef, isOver } = useDroppable({ id });
  return (
    <div ref={setNodeRef} className={`${className ?? ''} ${isOver ? 'ring-2 ring-blue-400 ring-dashed rounded-lg' : ''}`}>
      {children}
    </div>
  );
};

export const PipelineEditor: React.FC<PipelineEditorProps> = ({
  pipeline,
  available,
  onSave,
  saving,
  showFixedPhases = true,
  parallel = false,
  hookName,
}) => {
  const isDark = typeof document !== 'undefined' && document.documentElement.classList.contains('dark');
  const [popoverOpen, setPopoverOpen] = useState(false);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [configStep, setConfigStep] = useState<string | null>(null);

  // Split pipeline into hook steps (run as git hooks) and review steps (post-commit)
  const hookSteps = pipeline.filter(s => s.hook);
  const reviewSteps = pipeline.filter(s => !s.hook);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor),
  );

  const reviewTypes = reviewSteps.map(s => s.type);
  const hookTypes = new Set(hookSteps.map(s => s.type));
  const availableTypes = available.map(s => s.type);

  const removeReview = (type: string) => {
    onSave([...hookSteps, ...reviewSteps.filter(s => s.type !== type)]);
  };

  /** Remove from hook zone = move to review (strip hook field) */
  const unhook = (type: string) => {
    const step = hookSteps.find(s => s.type === type);
    if (!step) return;
    const { hook: _, ...reviewStep } = step;
    onSave([...hookSteps.filter(s => s.type !== type), ...reviewSteps, reviewStep]);
  };

  const add = (type: string) => {
    const step = available.find(s => s.type === type);
    if (step) {
      onSave([...hookSteps, ...reviewSteps, step]);
      setPopoverOpen(false);
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;

    const activeId = active.id as string;
    const overId = over.id as string;
    const isFromHooks = hookTypes.has(activeId);
    const isFromReview = reviewTypes.includes(activeId);

    // Cross-zone: review → hook zone drop target
    if (isFromReview && overId === 'hook-zone' && hookName) {
      const step = reviewSteps.find(s => s.type === activeId);
      if (step && isStaticAnalyser(step, staticTypes)) {
        onSave([...hookSteps, { ...step, hook: hookName }, ...reviewSteps.filter(s => s.type !== activeId)]);
      }
      return;
    }

    // Cross-zone: hook → review zone drop target
    if (isFromHooks && overId === 'review-zone') {
      unhook(activeId);
      return;
    }

    // Same-zone reorder within hooks
    if (isFromHooks && hookTypes.has(overId)) {
      const hookTypesList = hookSteps.map(s => s.type);
      const oldIdx = hookTypesList.indexOf(activeId);
      const newIdx = hookTypesList.indexOf(overId);
      if (oldIdx !== -1 && newIdx !== -1) {
        onSave([...arrayMove(hookSteps, oldIdx, newIdx), ...reviewSteps]);
      }
      return;
    }

    // Same-zone reorder within review
    if (isFromReview) {
      const oldIndex = reviewTypes.indexOf(activeId);
      const newIndex = reviewTypes.indexOf(overId);
      if (oldIndex !== -1 && newIndex !== -1) {
        onSave([...hookSteps, ...arrayMove(reviewSteps, oldIndex, newIndex)]);
      }
    }
  };

  const activeItems = reviewSteps.filter(s => availableTypes.includes(s.type));

  // Build set of step types known to be static from the available steps
  const staticTypes = new Set(available.filter(s => isStaticAnalyser(s)).map(s => s.type));

  // Split available items into static and agentic for the popover, excluding hook steps
  const popoverAvailable = available.filter(s => !hookTypes.has(s.type));
  const staticItems = popoverAvailable.filter(s => isStaticAnalyser(s, staticTypes)).sort((a, b) => (a.label ?? '').localeCompare(b.label ?? ''));
  const agenticItems = popoverAvailable.filter(s => !isStaticAnalyser(s, staticTypes)).sort((a, b) => (a.label ?? '').localeCompare(b.label ?? ''));

  return (
    <>
    <DndContext
      sensors={sensors}
      collisionDetection={zoneAwareCollision}
      onDragStart={(event: DragStartEvent) => setActiveId(event.active.id as string)}
      onDragEnd={(event: DragEndEvent) => { setActiveId(null); handleDragEnd(event); }}
      onDragCancel={() => setActiveId(null)}
    >
      {/* Hook zone — always visible when hookName is set */}
      {hookName && (
        <DroppableZone id="hook-zone" className="mb-2">
          <span className="text-[10px] font-semibold text-blue-500 dark:text-blue-400 uppercase tracking-wider">Hooks</span>
          {hookSteps.length > 0 ? (
            <ul className="flex items-center gap-2 flex-wrap mt-1 min-h-[76px]" role="list">
              <SortableContext items={hookSteps.map(s => s.type)} strategy={horizontalListSortingStrategy}>
                {hookSteps.map((step) => (
                  <SortableItem
                    key={step.type}
                    id={step.type}
                    label={step.label}
                    emoji={step.emoji}
                    saving={saving}
                    isStatic={isStaticAnalyser(step, staticTypes)}
                    onRemove={() => unhook(step.type)}
                  />
                ))}
              </SortableContext>
            </ul>
          ) : (
            <div className="mt-1 h-[76px] px-3 flex items-center justify-center rounded-lg border border-dashed border-blue-300 dark:border-blue-600">
              <p className="text-[11px] text-muted-foreground italic">Drag a static analyser here</p>
            </div>
          )}
        </DroppableZone>
      )}

      {/* Review zone */}
      {hookName && (
        <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Review</span>
      )}

      <DroppableZone id="review-zone">
        <ul className="flex items-center gap-2 flex-wrap mt-1" role="list">
          {/* Fixed phases — only shown for commit pipeline */}
          {showFixedPhases && FIXED_PHASES.map((phase) => {
            const colors = phaseColors(phase.hue, isDark);
            return (
              <Tooltip key={phase.label}>
                <TooltipTrigger asChild>
                  <li
                    role="listitem"
                    className="flex flex-col items-center justify-center gap-0.5 rounded-lg w-[104px] h-[76px] cursor-default p-2"
                    style={{
                      backgroundColor: colors.bg,
                      border: `1px solid ${colors.border}`,
                      color: colors.text,
                    }}
                  >
                    <span className="text-xl">{phase.emoji}</span>
                    <span className="text-xs font-medium text-center leading-tight">{phase.label}</span>
                  </li>
                </TooltipTrigger>
                <TooltipContent side="bottom">
                  <span className="text-xs">TDD phase — disable via enableTDD config</span>
                </TooltipContent>
              </Tooltip>
            );
          })}

          {/* Arrow separator */}
          {showFixedPhases && (
            <span className="text-muted-foreground text-xs">→</span>
          )}

          {/* Active items */}
          {parallel ? (
            /* Parallel mode — no ordering, no drag handles */
            activeItems.map((step) => (
              <ParallelItem
                key={step.type}
                id={step.type}
                label={step.label}
                emoji={step.emoji}
                saving={saving}
                isStatic={isStaticAnalyser(step, staticTypes)}
                isTollgate={step.mode === 'tollgate'}
                maxAttempts={step.maxAttempts}
                onRemove={() => removeReview(step.type)}
                onConfigure={() => setConfigStep(step.type)}
              />
            ))
          ) : (
            <SortableContext items={activeItems.map(s => s.type)} strategy={horizontalListSortingStrategy}>
              {activeItems.map((step) => (
                <SortableItem
                  key={step.type}
                  id={step.type}
                  label={step.label}
                  emoji={step.emoji}
                  saving={saving}
                  isStatic={isStaticAnalyser(step, staticTypes)}
                  isTollgate={step.mode === 'tollgate'}
                  maxAttempts={step.maxAttempts}
                  onRemove={() => removeReview(step.type)}
                  onConfigure={() => setConfigStep(step.type)}
                />
              ))}
            </SortableContext>
          )}

      {/* Add step button with popover */}
      <Popover open={popoverOpen} onOpenChange={setPopoverOpen}>
        <PopoverTrigger asChild>
          <button
            type="button"
            aria-label="Add step"
            disabled={saving}
            className="flex items-center justify-center rounded-lg border border-dashed border-gray-300 dark:border-gray-600 text-gray-400 dark:text-gray-500 hover:border-gray-400 dark:hover:border-gray-400 hover:text-gray-600 dark:hover:text-gray-300 cursor-pointer transition-colors w-12 h-[76px] disabled:cursor-not-allowed disabled:opacity-40"
          >
            <Plus className="h-5 w-5" />
          </button>
        </PopoverTrigger>
        <PopoverContent align="start" className="w-64 p-3 bg-white dark:bg-gray-800">
          {/* Static Analysers section */}
          {staticItems.length > 0 && (
            <div className="mb-3">
              <h4 className="text-[11px] font-semibold text-muted-foreground tracking-wider mb-1.5">STATIC ANALYSERS</h4>
              <div className="flex flex-col gap-0.5">
                {staticItems.map((step) => {
                  const isActive = reviewTypes.includes(step.type);
                  return (
                    <button
                      key={step.type}
                      type="button"
                      disabled={isActive}
                      onClick={() => add(step.type)}
                      className="flex items-center gap-2 px-2 py-1.5 rounded text-sm text-left hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
                    >
                      <span>{step.emoji}</span>
                      <span>{step.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* Agentic Analysers section */}
          {agenticItems.length > 0 && (
            <div>
              <h4 className="text-[11px] font-semibold text-muted-foreground tracking-wider mb-1.5">AGENTIC ANALYSERS</h4>
              <div className="flex flex-col gap-0.5">
                {agenticItems.map((step) => {
                  const isActive = reviewTypes.includes(step.type);
                  return (
                    <button
                      key={step.type}
                      type="button"
                      disabled={isActive}
                      onClick={() => add(step.type)}
                      className="flex items-center gap-2 px-2 py-1.5 rounded text-sm text-left hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
                    >
                      <span>{step.emoji}</span>
                      <span>{step.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}
        </PopoverContent>
      </Popover>
        </ul>
      </DroppableZone>

      {/* Drag overlay — shows avatar of dragged step */}
      <DragOverlay>
        {activeId ? (() => {
          const step = pipeline.find(s => s.type === activeId);
          if (!step) return null;
          return (
            <div className="flex flex-col items-center gap-0.5 rounded-lg border border-blue-400 bg-white dark:bg-gray-800 w-[104px] h-[76px] justify-center shadow-lg opacity-90">
              <span className="text-xl">{step.emoji}</span>
              <span className="text-xs font-medium text-center leading-tight">{step.label}</span>
            </div>
          );
        })() : null}
      </DragOverlay>
    </DndContext>

    {/* Step config popover */}
    {configStep && (() => {
      const stepIndex = pipeline.findIndex(s => s.type === configStep);
      const step = stepIndex !== -1 ? pipeline[stepIndex] : null;
      if (!step) return null;
      const mode = step.mode ?? 'review';
      const isTollgate = mode === 'tollgate';
      const threshold = step.analyzerThreshold?.min;
      const retries = step.maxAttempts;

      const updateStep = (updates: Partial<PipelineStep>) => {
        const updated = [...pipeline];
        updated[stepIndex] = { ...step, ...updates };
        onSave(updated);
      };

      return (
        <div
          data-testid="step-config-popover"
          className="fixed inset-0 z-50"
          onClick={() => setConfigStep(null)}
        >
          <div
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white dark:bg-gray-800 border rounded-lg shadow-lg p-4 w-72"
            onClick={(e) => e.stopPropagation()}
          >
            <h3 className="font-medium text-sm mb-3">{step.label}</h3>
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-xs font-medium text-muted-foreground">Mode</span>
                <button
                  type="button"
                  aria-label={isTollgate ? 'Toggle review' : 'Toggle tollgate'}
                  onClick={() => updateStep({ mode: isTollgate ? 'review' : 'tollgate' })}
                  className="text-xs px-2 py-0.5 rounded border hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                >
                  {isTollgate ? 'Tollgate' : 'Review'}
                </button>
              </div>
              {isTollgate && (
                <>
                  <div>
                    <label htmlFor="step-threshold" className="text-xs font-medium text-muted-foreground">Threshold</label>
                    <input
                      id="step-threshold"
                      type="number"
                      min={0}
                      max={100}
                      defaultValue={threshold ?? ''}
                      onBlur={(e) => {
                        const val = parseInt(e.target.value, 10);
                        if (!isNaN(val) && val >= 0 && val <= 100) updateStep({ analyzerThreshold: { min: val } });
                      }}
                      className="mt-0.5 w-full rounded border px-2 py-1 text-sm"
                    />
                  </div>
                  <div>
                    <label htmlFor="step-retries" className="text-xs font-medium text-muted-foreground">Max retries</label>
                    <input
                      id="step-retries"
                      type="number"
                      min={1}
                      max={10}
                      defaultValue={retries ?? ''}
                      onBlur={(e) => {
                        const val = parseInt(e.target.value, 10);
                        if (!isNaN(val) && val >= 1 && val <= 10) updateStep({ maxAttempts: val });
                      }}
                      className="mt-0.5 w-full rounded border px-2 py-1 text-sm"
                    />
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      );
    })()}
    </>
  );
};
