import React from 'react';
import { Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend
} from 'chart.js';
import { useTheme } from '../../contexts/ThemeContext';
import type { ChartData, ChartOptions } from 'chart.js';

// Register Chart.js components
ChartJS.register(ArcElement, Tooltip, Legend);

interface ProgressDonutChartProps {
  completed: number;
  total: number;
  label: string;
  superseded?: number;
}

const ProgressDonutChart: React.FC<ProgressDonutChartProps> = ({ completed, total, superseded = 0 }) => {
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === 'dark';

  const remaining = total - completed - superseded;

  // Build data array and labels based on what we have
  const hasSuperseded = superseded > 0;

  // If no total, show empty state
  const displayData = total > 0
    ? hasSuperseded
      ? [completed, superseded, remaining]
      : [completed, remaining]
    : [0, 1];

  const labels = hasSuperseded
    ? ['Completed', 'Skipped', 'Remaining']
    : ['Completed', 'Remaining'];

  const backgroundColors = hasSuperseded
    ? [
        '#10b981', // green for completed
        '#f97316', // orange for superseded/skipped
        isDark ? '#374151' : '#e5e7eb' // gray for remaining
      ]
    : [
        '#10b981', // green for completed
        isDark ? '#374151' : '#e5e7eb' // gray for remaining
      ];

  const data: ChartData<'doughnut'> = {
    labels,
    datasets: [
      {
        data: displayData,
        backgroundColor: backgroundColors,
        borderColor: isDark ? '#1f2937' : '#ffffff',
        borderWidth: 2,
      },
    ],
  };

  const options: ChartOptions<'doughnut'> = {
    responsive: true,
    maintainAspectRatio: true,
    layout: {
      padding: 0
    },
    plugins: {
      legend: {
        display: false
      },
      tooltip: {
        callbacks: {
          label: (context) => {
            const value = context.parsed;
            const percent = total > 0 ? Math.round((value / total) * 100) : 0;
            return `${context.label}: ${value} (${percent}%)`;
          }
        }
      }
    },
    cutout: '70%',
  };

  return (
    <div className="w-full h-[120px]">
      <Doughnut data={data} options={options} />
    </div>
  );
};

export default ProgressDonutChart;