import React from 'react';
import type { AnalyzerRunSummary } from '../types';
import { getSourceConfig } from '../utils/sourceIcons';
import { useTheme } from '../contexts/ThemeContext';

interface HygieneCardProps {
  analyzersRun: ReadonlyArray<AnalyzerRunSummary>;
}

/** Analyzers excluded from hygiene card (covered by specialist agents) */
const EXCLUDED_ANALYZERS = new Set(['npm-audit']);

export const HygieneCard: React.FC<HygieneCardProps> = ({ analyzersRun }) => {
  const filtered = analyzersRun.filter(a => !EXCLUDED_ANALYZERS.has(a.analyzerId));
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === 'dark';

  if (filtered.length === 0) return null;

  const totalIssues = filtered.reduce((sum, a) => sum + a.issueCount, 0);
  const allPassing = totalIssues === 0;

  const cardBg = allPassing
    ? (isDark ? 'oklch(0.25 0.03 145)' : 'oklch(0.96 0.02 145)')
    : (isDark ? 'oklch(0.25 0.04 55)' : 'oklch(0.96 0.03 55)');
  const cardBorder = allPassing
    ? (isDark ? 'oklch(0.35 0.05 145)' : 'oklch(0.85 0.05 145)')
    : (isDark ? 'oklch(0.4 0.08 55)' : 'oklch(0.8 0.08 55)');

  return (
    <div
      className="rounded-lg border p-4"
      style={{
        borderColor: cardBorder,
        backgroundColor: cardBg,
      }}
      data-testid="hygiene-card"
    >
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <span className="text-lg">🔬</span>
          <span className="font-medium text-sm">Static Analysis</span>
        </div>
        <span className={`text-sm font-bold ${allPassing ? 'text-green-600 dark:text-green-400' : 'text-gray-900 dark:text-gray-100'}`}>
          {totalIssues.toLocaleString()} {totalIssues === 1 ? 'issue' : 'issues'}
        </span>
      </div>

      <div className="space-y-2">
        {filtered.map(analyzer => {
          const config = getSourceConfig(analyzer.analyzerId);
          const isError = analyzer.status === 'failed' || analyzer.status === 'timeout';

          return (
            <div
              key={analyzer.analyzerId}
              className="flex items-center justify-between text-sm"
              data-testid="hygiene-row"
            >
              <div className="flex items-center gap-2">
                <div className={`flex items-center justify-center w-5 h-5 rounded ${config.bgColor}`}>
                  <span className={config.color}>{config.icon}</span>
                </div>
                <span className="text-gray-700 dark:text-gray-300">{config.label}</span>
              </div>
              {isError ? (
                <span className="text-amber-600 dark:text-amber-400 font-medium">{analyzer.status}</span>
              ) : analyzer.issueCount === 0 ? (
                <span className="text-green-600 dark:text-green-400 font-medium">0</span>
              ) : (
                <span className="text-gray-900 dark:text-gray-100 font-medium">
                  {analyzer.issueCount.toLocaleString()}
                </span>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};
