import React, { useEffect, useMemo, useState, useRef } from 'react';
import { BarChart3, Loader2 } from 'lucide-react';
import { Button } from './ui/button';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';
import { ReadinessHeader, buildSparklinePath } from './ReadinessHeader';
import { QualityStepCard } from './QualityStepCard';
import { HygieneCard } from './HygieneCard';
import { QualityChart } from './QualityChart';
import QualityDetail, { parseQualityData } from './QualityDetail';
import { QualityTechnicalDebt } from './QualityTechnicalDebt';
import { QualityImprovementPlan } from './QualityImprovementPlan';
import { QipFixPanel } from './QipFixPanel';
import { SkillInvocationPanel } from './SkillInvocationPanel';
import { useSkillInvocation } from '../hooks/useSkillInvocation';
import { useApiKeyStatus } from '../hooks/useApiKeyStatus';
import type {
  QualityScoresResponse,
  QualityRunSummary,
  QualityRunDetail,
  StepScoreResponse,
  QualityIssue,
  ParsedPlanData,
} from '../types';

/**
 * Non-overlapping: each category assigned to exactly ONE primary step.
 * Reverse of QualityDetail's CATEGORY_TO_STEP — must stay in sync.
 */
const STEP_TO_CATEGORIES: Record<string, ReadonlyArray<string>> = {
  'security': ['Security'],
  'performance': ['Performance'],
  'testing': ['Testing'],
  'code-quality': ['Maintainability', 'Architecture', 'Documentation', 'Operations', 'Reliability'],
  // These steps don't map to standard categories — their findings
  // need an `agent` field on issues to be attributed correctly.
  // For now they show 0 agent-sourced issues.
  'tdd-compliance': [],
  'dependency-audit': [],
};

/** Steps where the score is a real percentage (not issue-derived) */
const PERCENTAGE_STEPS = new Set(['coverage']);

/** Check if a step is backed by a static analyzer (not an LLM agent) */
export const isAnalyzerStep = (step: StepScoreResponse): boolean => !!step.analyzer;


function scoreToGrade(score: number): string {
  if (score >= 90) return 'A';
  if (score >= 80) return 'B';
  if (score >= 70) return 'C';
  if (score >= 60) return 'D';
  return 'F';
}

/**
 * Overlay quality run issue counts onto pipeline step cards.
 * Coverage keeps its real % score. Other steps get issue counts
 * from the run and display as grades.
 */
function overlayRunData(
  pipelineSteps: ReadonlyArray<StepScoreResponse>,
  issues: ReadonlyArray<QualityIssue>,
): ReadonlyArray<StepScoreResponse> {
  // Count non-hygiene issues per category (agent findings + npm-audit)
  const agentCategoryCounts = new Map<string, number>();
  // Also count npm-audit issues for the dependency-audit step
  let npmAuditCount = 0;
  for (const issue of issues) {
    if (issue.source === 'npm-audit') {
      npmAuditCount++;
      continue;
    }
    if (issue.source !== 'llm') continue;
    agentCategoryCounts.set(issue.category, (agentCategoryCounts.get(issue.category) ?? 0) + 1);
  }

  return pipelineSteps.map(step => {
    // Coverage keeps its pipeline score (real %)
    if (PERCENTAGE_STEPS.has(step.type)) {
      return step;
    }

    // Dependency audit: use npm-audit count + any LLM findings
    if (step.type === 'dependency-audit') {
      const findingsCount = npmAuditCount;
      const score = findingsCount === 0
        ? 100
        : Math.max(0, Math.round(100 - 20 * Math.log(1 + findingsCount)));
      return { ...step, score, findingsCount, passing: score >= step.threshold };
    }

    // For other steps, count agent findings in mapped categories
    const categories = STEP_TO_CATEGORIES[step.type];
    if (!categories) return step;

    const findingsCount = categories.reduce(
      (sum, cat) => sum + (agentCategoryCounts.get(cat) ?? 0),
      0,
    );

    // Score: 0 findings = 100, degrade with log curve
    const score = findingsCount === 0
      ? 100
      : Math.max(0, Math.round(100 - 20 * Math.log(1 + findingsCount)));
    const grade = scoreToGrade(score);

    return {
      ...step,
      score,
      findingsCount,
      passing: score >= step.threshold,
      grade,
    };
  });
}

function parsePlanData(planContent: string): ParsedPlanData | null {
  try {
    const jsonMatch = planContent.match(/```json\n([\s\S]*?)\n```/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[1]) as ParsedPlanData;
    }
  } catch (e) {
    console.error('Failed to parse plan data:', e);
  }
  return null;
}

interface QualityTabProps {
  repoId: string;
  runs: ReadonlyArray<QualityRunSummary>;
  selectedRun: QualityRunDetail | null;
  selectedRunId: string | null;
  onSelectRun: (runId: string) => void;
  onCriteriaChange?: (criteria: { passing: number; total: number }) => void;
  onRunDeleted?: () => void;
}

export const QualityTab: React.FC<QualityTabProps> = ({
  repoId,
  runs,
  selectedRun,
  selectedRunId,
  onSelectRun,
  onCriteriaChange,
  onRunDeleted,
}) => {
  const [pipelineData, setPipelineData] = useState<QualityScoresResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [showPanel, setShowPanel] = useState(false);
  const [activeTab, setActiveTab] = useState<'run' | 'plan' | 'fix'>('run');
  const [selectedStepType, setSelectedStepType] = useState<string | null>(null);
  const [agentIssues, setAgentIssues] = useState<QualityIssue[] | null>(null);
  const [agentIssuesLoading, setAgentIssuesLoading] = useState(false);
  const [agentIssuesError, setAgentIssuesError] = useState<string | null>(null);
  const [coverageBreakdown, setCoverageBreakdown] = useState<Record<string, { pct: number }> | null>(null);
  const [overallCoverage, setOverallCoverage] = useState<number | null>(null);
  const [skippedTests, setSkippedTests] = useState<number | null>(null);
  const [qipFixIds, setQipFixIds] = useState<Map<string, string>>(new Map());
  const [qipGenerating, setQipGenerating] = useState(false);
  const [selectedQipStepType, setSelectedQipStepType] = useState<string | null>(null);
  const [headerCollapsed, setHeaderCollapsed] = useState(false);
  const sentinelRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const { invoke, cancel, isRunning, output, toolCalls, error } = useSkillInvocation();
  const { hasClaudeCli, isLoading: isApiKeyLoading } = useApiKeyStatus();

  useEffect(() => {
    const fetchScores = async () => {
      setLoading(true);
      try {
        const response = await fetch(`/api/repos/${repoId}/quality-scores`);
        if (response.ok) {
          setPipelineData(await response.json());
        }
      } catch (err) {
        console.error('[QualityTab] Failed to fetch quality scores:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchScores();
  }, [repoId]);

  // Load existing QIPs on mount
  useEffect(() => {
    const fetchQips = async () => {
      try {
        const res = await fetch(`/api/repos/${repoId}/qips`);
        if (res.ok) {
          const data = await res.json();
          const ids = new Map<string, string>();
          for (const qip of data.qips) {
            // qip.id is "qip-security" → stepType is "security"
            const stepType = qip.id.replace(/^qip-/, '');
            ids.set(stepType, qip.id);
          }
          setQipFixIds(ids);
        }
      } catch (err) {
        console.error('[QualityTab] Failed to fetch QIPs:', err);
      }
    };
    fetchQips();
  }, [repoId]);

  const trend = useMemo(
    () => runs.slice(0, 5).reverse().map(r => r.score),
    [runs],
  );

  const handleRunQuality = () => {
    setShowPanel(true);
    const prompt = 'Run a comprehensive quality analysis on this repository';
    invoke('quality', prompt, { repoId });
  };

  const handleClosePanel = () => {
    if (!isRunning) {
      setShowPanel(false);
    }
  };

  const handleDeleteRun = async () => {
    if (!selectedRunId || !repoId) return;
    try {
      const response = await fetch(`/api/repos/${repoId}/quality/${selectedRunId}`, { method: 'DELETE' });
      if (response.ok) {
        onRunDeleted?.();
      }
    } catch (err) {
      console.error('[QualityTab] Failed to delete run:', err);
    }
  };

  const selectedRunSummary = useMemo(
    () => selectedRunId ? runs.find(r => r.runId === selectedRunId) ?? null : null,
    [runs, selectedRunId],
  );

  const parsedRunData = useMemo(() => {
    if (!selectedRun?.rawContent) return null;
    return parseQualityData(selectedRun.rawContent);
  }, [selectedRun?.rawContent]);

  const parsedPlan = useMemo(() => {
    if (!selectedRun?.planContent) return null;
    return parsePlanData(selectedRun.planContent);
  }, [selectedRun?.planContent]);

  // Reset per-run state when switching runs
  useEffect(() => {
    setSelectedStepType(null);
    setAgentIssues(null);
    setAgentIssuesError(null);
  }, [selectedRunId]);

  // Fetch coverage aggregate data when a run is selected
  // Try agent data first (backward compat), fall back to static analyser metrics
  useEffect(() => {
    setCoverageBreakdown(null);
    setOverallCoverage(null);
    setSkippedTests(null);
    if (!selectedRunId) return;

    const applyStaticFallback = () => {
      if (selectedRun?.coverageMetrics?.overallCoverage != null) {
        setOverallCoverage(selectedRun.coverageMetrics.overallCoverage);
      }
    };

    (async () => {
      try {
        const res = await fetch(`/api/repos/${repoId}/quality/${selectedRunId}/agents/coverage`);
        if (res.ok) {
          const data: unknown = await res.json();
          if (data && typeof data === 'object' && 'overallCoverage' in data && typeof (data as Record<string, unknown>).overallCoverage === 'number') {
            setOverallCoverage((data as Record<string, unknown>).overallCoverage as number);
            if ('packageBreakdown' in data) {
              setCoverageBreakdown((data as Record<string, unknown>).packageBreakdown as Record<string, { pct: number }>);
            }
            if ('skippedTests' in data && typeof (data as Record<string, unknown>).skippedTests === 'number') {
              setSkippedTests((data as Record<string, unknown>).skippedTests as number);
            }
            return;
          }
        }
        applyStaticFallback();
      } catch {
        applyStaticFallback();
      }
    })();
  }, [repoId, selectedRunId, selectedRun?.coverageMetrics]);

  // Pipeline steps overlaid with quality run data when available.
  // Prefer agentFindings (per-agent counts from assembly) when present.
  // Fall back to category-mapping heuristic for legacy runs.
  const stepCards = useMemo(() => {
    const pipelineSteps = pipelineData?.steps ?? [];
    if (!parsedRunData) return pipelineSteps;

    // New path: use agentFindings from assembly service
    const af = parsedRunData.agentFindings as Record<string, { issueCount: number }> | undefined;
    if (af && Object.keys(af).length > 0) {
      return pipelineSteps.map(step => {
        if (PERCENTAGE_STEPS.has(step.type)) {
          const coverageScore = overallCoverage ?? step.score;
          const coveragePassing = coverageScore >= step.threshold;
          return {
            ...step,
            score: Math.round(coverageScore),
            passing: coveragePassing,
            ...(coverageBreakdown ? { packageBreakdown: coverageBreakdown } : {}),
            ...(skippedTests != null ? { skippedTests } : {}),
          };
        }
        const finding = af[step.type];
        const findingsCount = finding?.issueCount ?? 0;
        return { ...step, findingsCount, passing: findingsCount === 0 };
      });
    }

    // Legacy fallback: reverse-map from issue categories
    if (parsedRunData.issues && parsedRunData.issues.length > 0) {
      return overlayRunData(pipelineSteps, parsedRunData.issues);
    }
    return pipelineSteps;
  }, [parsedRunData, pipelineData, coverageBreakdown, overallCoverage, skippedTests]);

  // Build readiness from step cards
  const readinessData = useMemo((): QualityScoresResponse | null => {
    if (stepCards.length > 0) {
      const passing = stepCards.filter(s => s.passing).length;
      const overallScore = selectedRunSummary?.score ?? pipelineData?.overallScore ?? 0;
      return {
        steps: [...stepCards],
        overallScore,
        readiness: { passing, total: stepCards.length },
      };
    }
    return pipelineData;
  }, [stepCards, selectedRunSummary, pipelineData]);

  // Notify parent of criteria changes for tab badge
  useEffect(() => {
    if (readinessData && onCriteriaChange) {
      onCriteriaChange(readinessData.readiness);
    }
  }, [readinessData, onCriteriaChange]);

  // Observe sentinel to toggle compact header
  useEffect(() => {
    const sentinel = sentinelRef.current;
    const scrollContainer = scrollContainerRef.current;
    if (!sentinel || !scrollContainer) return;

    const observer = new IntersectionObserver(
      (entries) => {
        setHeaderCollapsed(!entries[0].isIntersecting);
      },
      { root: scrollContainer, threshold: 0 }
    );

    observer.observe(sentinel);
    return () => observer.disconnect();
    // Re-run when loading changes: refs are null during loading state,
    // so the observer must be set up after data loads and refs mount.
  }, [loading]);

  const handleGenerateQip = async (stepType: string) => {
    if (!selectedRunId) return;
    setQipGenerating(true);
    try {
      const res = await fetch(`/api/repos/${repoId}/quality/${selectedRunId}/qip/${stepType}`, { method: 'POST' });
      if (res.ok) {
        const data = await res.json();
        setQipFixIds(prev => new Map(prev).set(stepType, data.fixId));
        setSelectedQipStepType(stepType);
        setActiveTab('fix');
      }
    } finally {
      setQipGenerating(false);
    }
  };

  const handleStepClick = async (stepType: string) => {
    if (selectedStepType === stepType) {
      setSelectedStepType(null);
      setAgentIssues(null);
      setAgentIssuesError(null);
      return;
    }
    setSelectedStepType(stepType);
    setAgentIssuesError(null);

    // Hygiene issues come from parsed run data, not from an agent file
    if (stepType === 'hygiene') {
      setAgentIssues(null);
      return;
    }

    // Fetch agent issues from per-agent output file (files are named by step type)
    if (!stepType || !selectedRunId) {
      setAgentIssues(null);
      return;
    }

    setAgentIssuesLoading(true);
    try {
      const response = await fetch(`/api/repos/${repoId}/quality/${selectedRunId}/agents/${stepType}`);
      if (!response.ok) {
        setAgentIssues(null);
        setAgentIssuesError(`Failed to load agent data (${response.status})`);
        return;
      }
      const data: unknown = await response.json();
      const issues = Array.isArray(data)
        ? data as QualityIssue[]
        : data && typeof data === 'object' && 'issues' in data && Array.isArray((data as Record<string, unknown>).issues)
          ? (data as { issues: QualityIssue[] }).issues
          : [];
      setAgentIssues(issues);
    } catch {
      setAgentIssues(null);
      setAgentIssuesError('Failed to fetch agent data');
    } finally {
      setAgentIssuesLoading(false);
    }
  };

  // Analyzer IDs already shown by the HygieneCard (from analysersRun)
  const hygieneAnalyzerIds = useMemo(() => {
    const ids = new Set<string>();
    for (const a of parsedRunData?.analyzersRun ?? []) {
      ids.add(a.analyzerId);
    }
    return ids;
  }, [parsedRunData?.analyzersRun]);

  const staticSteps = useMemo(
    () => [...stepCards]
      .filter(s => isAnalyzerStep(s) && !hygieneAnalyzerIds.has(s.type))
      .sort((a, b) => {
        if (a.type === 'coverage') return -1;
        if (b.type === 'coverage') return 1;
        return b.findingsCount - a.findingsCount;
      }),
    [stepCards, hygieneAnalyzerIds],
  );

  const agenticSteps = useMemo(
    () => [...stepCards]
      .filter(s => !isAnalyzerStep(s))
      .sort((a, b) => {
        if (a.findingsCount === 0 && b.findingsCount > 0) return 1;
        if (a.findingsCount > 0 && b.findingsCount === 0) return -1;
        return b.findingsCount - a.findingsCount;
      }),
    [stepCards],
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8" data-testid="quality-tab-loading">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const sparklinePath = trend.length >= 2 ? buildSparklinePath(trend) : null;

  return (
    <>
      <div className="flex flex-col h-full" data-testid="quality-tab">
        {/* Compact header — visible when full header scrolls out */}
        <div
          data-testid="quality-compact-header"
          className="flex-shrink-0 border-b px-4 py-2 flex items-center justify-between transition-all"
          style={{ display: headerCollapsed ? 'flex' : 'none' }}
        >
          <div className="flex items-center gap-3">
            <span className="text-lg font-bold">
              {readinessData?.readiness.passing ?? 0}/{readinessData?.readiness.total ?? 0}
            </span>
            <span className="text-sm text-muted-foreground">criteria passing</span>
          </div>
          <div className="flex items-center gap-4">
            {sparklinePath && (
              <svg width={80} height={24} className="text-blue-500">
                <path d={sparklinePath} fill="none" stroke="currentColor" strokeWidth={1.5} />
              </svg>
            )}
            {!isApiKeyLoading && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <span>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handleRunQuality}
                      disabled={!hasClaudeCli || isRunning}
                      className="flex items-center gap-2"
                    >
                      {isRunning ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : (
                        <BarChart3 className="h-4 w-4" />
                      )}
                      {isRunning ? 'Running...' : 'Run'}
                    </Button>
                  </span>
                </TooltipTrigger>
                {!hasClaudeCli && (
                  <TooltipContent>
                    Claude CLI required - use the /quality skill in Claude Code instead
                  </TooltipContent>
                )}
              </Tooltip>
            )}
          </div>
        </div>

        <div ref={scrollContainerRef} className="flex-1 overflow-auto">
        {/* Header: ReadinessHeader + sparkline (left) | Chart (right) */}
        <div className="px-4 pt-2 pb-2">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <div className="space-y-3">
              <ReadinessHeader
                data={readinessData}
                trend={trend}
                selectedRun={selectedRunSummary}
                onRunQuality={handleRunQuality}
                onDeleteRun={selectedRunId ? handleDeleteRun : undefined}
                isRunning={isRunning}
                hasClaudeCli={hasClaudeCli}
                isApiKeyLoading={isApiKeyLoading}
              />
              {parsedRunData?.technicalDebt && (
                <QualityTechnicalDebt technicalDebt={parsedRunData.technicalDebt} />
              )}
            </div>
            <QualityChart
              runs={runs}
              selectedRunId={selectedRunId}
              onSelectRun={onSelectRun}
            />
          </div>
        </div>

        {/* Sentinel — triggers compact header when scrolled past */}
        <div ref={sentinelRef} className="h-0" />

        {/* Run/Plan tabs — full width */}
        {selectedRun ? (
          <div className="flex-1 flex flex-col">
            {/* Tab bar */}
            <div className="flex border-b border-gray-200 dark:border-gray-700 px-4" role="tablist">
              <button
                role="tab"
                aria-selected={activeTab === 'run'}
                onClick={() => setActiveTab('run')}
                className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                  activeTab === 'run'
                    ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                    : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                }`}
              >
                Run
              </button>
              {qipFixIds.size > 0 && (
                <button
                  role="tab"
                  aria-selected={activeTab === 'fix'}
                  onClick={() => setActiveTab('fix')}
                  className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                    activeTab === 'fix'
                      ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                      : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                  }`}
                >
                  Fix
                </button>
              )}
              {parsedPlan && (
                <button
                  role="tab"
                  aria-selected={activeTab === 'plan'}
                  onClick={() => setActiveTab('plan')}
                  className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                    activeTab === 'plan'
                      ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                      : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                  }`}
                >
                  Plan
                </button>
              )}
            </div>

            {/* Tab content */}
            {activeTab === 'run' ? (
              <div className="flex-1 p-4">
                <div className="grid grid-cols-1 lg:grid-cols-[280px_1fr] gap-4">
                  {/* Left sidebar: step cards */}
                  <div className="space-y-3" data-testid="quality-step-grid">
                    {/* Static Analysis section */}
                    <div className="text-xs font-semibold uppercase tracking-wider text-gray-500 dark:text-gray-400 pt-1">Static Analysis</div>
                    {parsedRunData?.analyzersRun && parsedRunData.analyzersRun.length > 0 && (
                      <div
                        onClick={() => handleStepClick('hygiene')}
                        className={`cursor-pointer rounded-lg transition-all ${selectedStepType === 'hygiene' ? 'ring-2 ring-blue-500' : ''}`}
                      >
                        <HygieneCard analyzersRun={parsedRunData.analyzersRun} />
                      </div>
                    )}
                    {staticSteps.map(step => (
                      <div
                        key={step.type}
                        onClick={() => handleStepClick(step.type)}
                        className={`cursor-pointer rounded-lg transition-all ${selectedStepType === step.type ? 'ring-2 ring-blue-500' : ''}`}
                      >
                        <QualityStepCard step={step} hasQip={qipFixIds.has(step.type)} />
                      </div>
                    ))}

                    {/* Agentic Analysis section */}
                    <div className="text-xs font-semibold uppercase tracking-wider text-gray-500 dark:text-gray-400 pt-2">Agentic Analysis</div>
                    {agenticSteps.map(step => (
                      <div
                        key={step.type}
                        onClick={() => handleStepClick(step.type)}
                        className={`cursor-pointer rounded-lg transition-all ${selectedStepType === step.type ? 'ring-2 ring-blue-500' : ''}`}
                      >
                        <QualityStepCard step={step} hasQip={qipFixIds.has(step.type)} />
                      </div>
                    ))}
                  </div>

                  {/* Right: filtered issues for selected step */}
                  <QualityDetail
                    selectedRun={selectedRun}
                    stepCards={stepCards}
                    selectedStepType={selectedStepType}
                    agentIssues={agentIssues}
                    agentIssuesLoading={agentIssuesLoading}
                    agentIssuesError={agentIssuesError}
                    onGenerateQip={handleGenerateQip}
                    onViewQip={(stepType) => {
                      setSelectedQipStepType(stepType);
                      setActiveTab('fix');
                    }}
                    qipGenerating={qipGenerating}
                    hasQip={selectedStepType ? qipFixIds.has(selectedStepType) : false}
                  />
                </div>
              </div>
            ) : activeTab === 'fix' ? (
              <QipFixPanel
                steps={stepCards}
                qipFixIds={qipFixIds}
                selectedStepType={selectedQipStepType}
                onSelectStep={setSelectedQipStepType}
                repoId={repoId}
              />
            ) : (
              <div className="flex-1 p-4">
                {parsedPlan && <QualityImprovementPlan plan={parsedPlan} />}
              </div>
            )}
          </div>
        ) : (
          <div className="flex-1 flex items-center justify-center py-12">
            {runs.length === 0 ? (
              <div className="text-center">
                <div className="text-6xl mb-4">📊</div>
                <p className="text-text-secondary">No quality runs yet</p>
                <p className="text-text-tertiary text-sm mt-2">
                  {hasClaudeCli
                    ? 'Click "Run Quality Analysis" to get started'
                    : 'Use the /quality skill in Claude Code'}
                </p>
              </div>
            ) : (
              <p className="text-text-secondary">Select a run from the chart to view details</p>
            )}
          </div>
        )}
        </div>{/* end scrollContainerRef */}
      </div>{/* end quality-tab */}

      <SkillInvocationPanel
        isOpen={showPanel}
        onClose={handleClosePanel}
        skillName="quality"
        output={output}
        toolCalls={toolCalls}
        isRunning={isRunning}
        error={error}
        onCancel={cancel}
      />
    </>
  );
};
