import React, { useRef, useEffect, useCallback } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import type { Chart } from 'chart.js';
import { useTheme } from '../contexts/ThemeContext';
import { getChartOptions } from './charts/chartSetup';
import type { QualityRunSummary } from '../types';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

interface QualityChartProps {
  runs: ReadonlyArray<QualityRunSummary>;
  selectedRunId: string | null;
  onSelectRun: (runId: string) => void;
}

function formatShortDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
  });
}

export const QualityChart: React.FC<QualityChartProps> = ({ runs, selectedRunId, onSelectRun }) => {
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === 'dark';
  const chartTheme = getChartOptions(isDark);
  const chartRef = useRef<Chart<'line'> | null>(null);
  const animFrameRef = useRef<number>(0);
  const selectedIndexRef = useRef<number>(-1);

  // Track selected index for the plugin
  useEffect(() => {
    const sortedRunsList = [...runs].sort((a, b) => a.runId.localeCompare(b.runId));
    selectedIndexRef.current = selectedRunId
      ? sortedRunsList.findIndex(r => r.runId === selectedRunId)
      : sortedRunsList.length - 1;
  }, [runs, selectedRunId]);

  // Animate pulse ring via requestAnimationFrame
  const animate = useCallback(() => {
    const chart = chartRef.current;
    if (!chart) { animFrameRef.current = requestAnimationFrame(animate); return; }

    const idx = selectedIndexRef.current;
    if (idx < 0) { animFrameRef.current = requestAnimationFrame(animate); return; }

    // Force chart redraw which triggers the plugin
    chart.draw();

    const meta = chart.getDatasetMeta(0);
    const point = meta.data[idx];
    if (point) {
      const ctx = chart.ctx;
      const time = Date.now() / 1000;
      const alpha = 0.2 + 0.3 * Math.sin(time * 3);
      const radius = 14 + 4 * Math.sin(time * 3);

      ctx.save();
      ctx.beginPath();
      ctx.arc(point.x, point.y, radius, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(59, 130, 246, ${alpha})`;
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.restore();
    }

    animFrameRef.current = requestAnimationFrame(animate);
  }, []);

  useEffect(() => {
    animFrameRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animFrameRef.current);
  }, [animate]);

  if (runs.length === 0) {
    return (
      <div className="flex items-center justify-center">
        <p className="text-sm text-muted-foreground">No quality data yet</p>
      </div>
    );
  }

  const sortedRuns = [...runs].sort((a, b) => a.runId.localeCompare(b.runId));

  const minSlots = 10;
  const paddingCount = Math.max(0, minSlots - sortedRuns.length);
  const paddedLabels = [
    ...sortedRuns.map(r => formatShortDate(r.date)),
    ...Array(paddingCount).fill(''),
  ];
  const paddedData = [
    ...sortedRuns.map(r => r.issueCount),
    ...Array(paddingCount).fill(null),
  ];

  const selectedIndex = selectedRunId
    ? sortedRuns.findIndex(r => r.runId === selectedRunId)
    : -1;

  // Auto-select last run with pulse ring effect
  const effectiveSelectedIndex = selectedIndex >= 0 ? selectedIndex : sortedRuns.length - 1;

  const chartData = {
    labels: paddedLabels,
    datasets: [
      {
        label: 'Issues',
        data: paddedData,
        borderColor: '#3b82f6',
        backgroundColor: 'rgba(59, 130, 246, 0.1)',
        fill: true,
        tension: 0.3,
        pointRadius: sortedRuns.map((_, i) => i === effectiveSelectedIndex ? 10 : 6),
        pointHoverRadius: 10,
        pointBackgroundColor: sortedRuns.map(() => '#3b82f6'),
        pointBorderColor: sortedRuns.map((_, i) =>
          i === effectiveSelectedIndex ? '#fff' : 'transparent'
        ),
        pointBorderWidth: sortedRuns.map((_, i) =>
          i === effectiveSelectedIndex ? 3 : 0
        ),
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    onClick: (_event: unknown, elements: ReadonlyArray<{ index: number }>) => {
      if (elements.length > 0) {
        const idx = elements[0].index;
        if (idx < sortedRuns.length) {
          onSelectRun(sortedRuns[idx].runId);
        }
      }
    },
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          label: (context: { dataIndex: number; parsed: { y: number | null } }) => {
            const run = sortedRuns[context.dataIndex];
            if (!run) return [];
            return [
              `Issues: ${run.issueCount}`,
            ];
          },
        },
      },
    },
    scales: {
      x: {
        ticks: { color: chartTheme.textColor },
        grid: { color: chartTheme.gridColor, display: false },
      },
      y: {
        beginAtZero: true,
        ticks: {
          color: chartTheme.textColor,
          callback: function (value: string | number) { return value; },
        },
        grid: { color: chartTheme.gridColor },
      },
    },
  };

  return (
    <div>
      <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Issues Over Time</h3>
      <div className="h-36" data-testid="quality-chart-container">
        <Line ref={chartRef} data={chartData} options={chartOptions} />
      </div>
    </div>
  );
};
