import React from 'react';
import { cn } from '@/lib/utils';

interface SelectableCardProps {
  isSelected: boolean;
  isCompleted?: boolean;
  onClick: () => void;
  children: React.ReactNode;
  className?: string;
  'data-testid'?: string;
}

const SelectableCard: React.FC<SelectableCardProps> = ({
  isSelected,
  isCompleted = false,
  onClick,
  children,
  className,
  'data-testid': dataTestId,
}) => {
  return (
    <div
      data-testid={dataTestId}
      data-selected={isSelected}
      data-completed={isCompleted}
      onClick={onClick}
      className={cn(
        'p-3 rounded-lg cursor-pointer transition-all duration-200',
        'border',
        // Completed + Selected
        isCompleted && isSelected && [
          'bg-gradient-to-br from-green-100 to-emerald-100 dark:from-green-900/40 dark:to-emerald-900/40',
          'border-green-500 dark:border-green-500',
          'ring-2 ring-green-400/50 dark:ring-green-600/50',
          'shadow-md',
        ],
        // Completed + Not Selected
        isCompleted && !isSelected && [
          'bg-gradient-to-br from-green-50 to-emerald-50 dark:from-green-950/30 dark:to-emerald-950/30',
          'border-green-300/50 dark:border-green-700/50',
          'hover:border-green-400 dark:hover:border-green-600',
          'hover:shadow-sm',
        ],
        // Not Completed + Selected
        !isCompleted && isSelected && [
          'bg-purple-100/60 dark:bg-purple-900/30',
          'border-purple-400 dark:border-purple-500',
          'ring-2 ring-purple-300/30 dark:ring-purple-600/30',
          'shadow-sm',
        ],
        // Not Completed + Not Selected
        !isCompleted && !isSelected && [
          'bg-card',
          'border-border',
          'hover:bg-accent/50',
          'hover:border-primary/50',
          'hover:shadow-sm',
        ],
        className
      )}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
    >
      {children}
    </div>
  );
};

export { SelectableCard };
