import { useState, useEffect } from 'react';
import { X, Loader2, FileCode, FolderPlus, CheckSquare, AlertCircle } from 'lucide-react';
import type { TaskDetail, FeatureMarkdown, Task } from '../types';
import { deriveTddPhase } from '../utils/tdd-phases';
import { useDetailsPopover } from './GlobalDetailsPopover';
import { useTaskTelemetry } from '../hooks/useTaskTelemetry';
import type { TaskRefInput } from '../hooks/useTaskTelemetry';
import { TaskTimeline } from './TaskTimeline';
import { getStepEmoji, getStepLabel } from '../utils/step-display';

const formatDuration = (startIso?: string, endIso?: string): string => {
  if (!startIso || !endIso) return '';
  const ms = new Date(endIso).getTime() - new Date(startIso).getTime();
  if (ms < 0) return '';
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  if (minutes === 0) return `${seconds}s`;
  return `${minutes}m ${seconds}s`;
};

interface TaskDetailPanelProps {
  isOpen: boolean;
  onClose: () => void;
  repoId: string;
  planId?: string;
  featureId?: string;
  fixId?: string;
  taskNumber: number;
  /** The task from progress.json with commit tracking info */
  progressTask?: Task;
}

const TaskDetailContent: React.FC<{
  repoId: string;
  planId?: string;
  featureId?: string;
  fixId?: string;
  taskNumber: number;
  progressTask?: Task;
  onClose: () => void;
}> = ({ repoId, planId, featureId, fixId, taskNumber, progressTask, onClose }) => {
  const [taskDetail, setTaskDetail] = useState<TaskDetail | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'details' | 'timeline'>('details');

  const taskId = progressTask?.description ?? '';
  const taskRef: TaskRefInput | null = taskId
    ? fixId
      ? { kind: 'fix', fixId, taskId }
      : (planId && featureId)
        ? { kind: 'prd', prdId: planId, featureId, taskId }
        : null
    : null;

  const { events: telemetryEvents, loading: telemetryLoading, error: telemetryError } =
    useTaskTelemetry(repoId, taskRef, activeTab === 'timeline');

  useEffect(() => {
    if (repoId && taskNumber > 0) {
      if (planId && featureId) {
        fetchFeatureTaskDetail();
      } else if (fixId) {
        fetchFixTaskDetail();
      }
    }
  }, [repoId, planId, featureId, fixId, taskNumber]);

  const fetchFeatureTaskDetail = async () => {
    setLoading(true);
    setError(null);
    const url = `/api/repos/${repoId}/plans/${planId}/features/${featureId}`;
    try {
      const response = await fetch(url);
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Failed to fetch feature details (${response.status})`);
      }
      const data = await response.json();
      const feature: FeatureMarkdown = data.feature;

      const task = feature.tasks.find(t => t.number === taskNumber);
      if (!task) {
        throw new Error(`Task ${taskNumber} not found in feature`);
      }
      setTaskDetail(task);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  const fetchFixTaskDetail = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/repos/${repoId}/fixes/${fixId}`);
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Failed to fetch fix details (${response.status})`);
      }
      const data = await response.json();
      const task = data.fix.parsedTasks?.find((t: TaskDetail) => t.number === taskNumber);
      if (!task) {
        throw new Error(`Task ${taskNumber} not found in fix`);
      }
      setTaskDetail(task);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  // Derive current TDD phase for completed tasks
  const currentPhase = progressTask?.status === 'completed'
    ? deriveTddPhase(progressTask)
    : undefined;

  // Get status color based on progress task status
  const getStatusColor = () => {
    if (!progressTask) return 'text-gray-500';
    switch (progressTask.status) {
      case 'completed': {
        if (currentPhase?.startsWith('review:') || currentPhase?.startsWith('refactor:')) {
          return 'text-purple-600 dark:text-purple-400';
        }
        return 'text-green-600 dark:text-green-400';
      }
      case 'in_progress':
        return 'text-blue-600 dark:text-blue-400';
      case 'superseded':
        return 'text-orange-600 dark:text-orange-400';
      default:
        return 'text-gray-500';
    }
  };

  const getStatusLabel = () => {
    if (!progressTask) return 'Not Started';
    switch (progressTask.status) {
      case 'completed': {
        if (currentPhase === 'complete') return 'Complete';
        if (currentPhase?.startsWith('review:')) {
          const type = currentPhase.slice('review:'.length);
          return `${type.charAt(0).toUpperCase() + type.slice(1)} Review`;
        }
        if (currentPhase?.startsWith('refactor:')) {
          const type = currentPhase.slice('refactor:'.length);
          return `${type.charAt(0).toUpperCase() + type.slice(1)} Refactor`;
        }
        return 'Completed';
      }
      case 'in_progress':
        return 'In Progress';
      case 'superseded':
        return 'Superseded';
      default:
        return 'Not Started';
    }
  };

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="bg-gray-200 dark:bg-gray-900 border-b border-border dark:border-dark-border">
        <div className="flex items-center justify-between p-4">
          <div className="flex items-center gap-2">
            <span className="text-xs font-mono text-muted-foreground">
              Task {taskNumber}
            </span>
            <span className={`text-xs font-medium ${getStatusColor()}`}>
              {getStatusLabel()}
            </span>
          </div>
          <button
            onClick={onClose}
            aria-label="Close"
            className="p-1 rounded-md hover:bg-gray-300 dark:hover:bg-gray-800 transition-colors"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {taskDetail && (
          <div className="px-4 pb-4">
            <h2 className="text-lg font-semibold">{taskDetail.title}</h2>
          </div>
        )}

        {/* Tab bar */}
        <div className="flex border-b border-border dark:border-dark-border px-4" role="tablist">
          <button
            role="tab"
            aria-selected={activeTab === 'details'}
            onClick={() => setActiveTab('details')}
            className={`px-3 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'details'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
          >
            Details
          </button>
          <button
            role="tab"
            aria-selected={activeTab === 'timeline'}
            onClick={() => setActiveTab('timeline')}
            className={`px-3 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'timeline'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
          >
            Timeline
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4">
        {activeTab === 'timeline' ? (
          telemetryLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : telemetryError ? (
            <div className="flex items-start gap-3 p-4 bg-red-50 dark:bg-red-900/20 rounded-lg">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-red-700 dark:text-red-400">Error loading timeline</p>
                <p className="text-sm text-red-600 dark:text-red-300 mt-1">{telemetryError}</p>
              </div>
            </div>
          ) : (
            <TaskTimeline events={telemetryEvents} />
          )
        ) : (
        <>
        {loading && (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        )}

        {error && (
          <div className="flex items-start gap-3 p-4 bg-red-50 dark:bg-red-900/20 rounded-lg">
            <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" />
            <div>
              <p className="font-medium text-red-700 dark:text-red-400">Error loading task details</p>
              <p className="text-sm text-red-600 dark:text-red-300 mt-1">{error}</p>
            </div>
          </div>
        )}

        {/* Fallback: show progressTask description when no API data (fix tasks) */}
        {!taskDetail && !loading && !error && progressTask && (
          <div className="space-y-6">
            <div>
              <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2">
                Description
              </h3>
              <p className="text-sm whitespace-pre-wrap">{progressTask.description}</p>
            </div>

            {/* Superseded Note */}
            {progressTask.status === 'superseded' && progressTask.note && (
              <div className="p-3 bg-orange-50 dark:bg-orange-900/20 rounded-lg border border-orange-200 dark:border-orange-800">
                <h3 className="text-xs font-semibold text-orange-700 dark:text-orange-400 uppercase mb-1">
                  Superseded Reason
                </h3>
                <p className="text-sm text-orange-600 dark:text-orange-300">{progressTask.note}</p>
              </div>
            )}
          </div>
        )}

        {taskDetail && !loading && !error && (
          <div className="space-y-6">
            {/* Description */}
            {taskDetail.description && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2">
                  Description
                </h3>
                <p className="text-sm whitespace-pre-wrap">{taskDetail.description}</p>
              </div>
            )}

            {/* Files to Modify */}
            {taskDetail.filesToModify && taskDetail.filesToModify.length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2 flex items-center gap-2">
                  <FileCode className="h-4 w-4" />
                  Files to Modify
                </h3>
                <ul className="space-y-1">
                  {taskDetail.filesToModify.map((file, index) => (
                    <li
                      key={index}
                      className="text-sm font-mono bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded"
                    >
                      {file}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Files to Create */}
            {taskDetail.filesToCreate && taskDetail.filesToCreate.length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2 flex items-center gap-2">
                  <FolderPlus className="h-4 w-4" />
                  Files to Create
                </h3>
                <ul className="space-y-1">
                  {taskDetail.filesToCreate.map((file, index) => (
                    <li
                      key={index}
                      className="text-sm font-mono bg-green-50 dark:bg-green-900/20 px-2 py-1 rounded text-green-700 dark:text-green-400"
                    >
                      {file}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Expected Changes */}
            {taskDetail.expectedChanges && taskDetail.expectedChanges.length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2 flex items-center gap-2">
                  <CheckSquare className="h-4 w-4" />
                  Expected Changes
                </h3>
                <ul className="space-y-2">
                  {taskDetail.expectedChanges.map((change, index) => (
                    <li key={index} className="text-sm flex items-start gap-2">
                      <span className="text-muted-foreground">•</span>
                      <span>{change}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Superseded Note */}
            {progressTask?.status === 'superseded' && progressTask.note && (
              <div className="p-3 bg-orange-50 dark:bg-orange-900/20 rounded-lg border border-orange-200 dark:border-orange-800">
                <h3 className="text-xs font-semibold text-orange-700 dark:text-orange-400 uppercase mb-1">
                  Superseded Reason
                </h3>
                <p className="text-sm text-orange-600 dark:text-orange-300">{progressTask.note}</p>
              </div>
            )}
          </div>
        )}
        </>
        )}
      </div>

      {/* Footer - Commit Trail */}
      {progressTask && (progressTask.testCommitSha || progressTask.commitSha || progressTask.reviews) && (
        <div className="border-t border-border dark:border-dark-border p-4">
          <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-3">
            Commit Trail
          </h3>
          <div className="space-y-2">
            {progressTask.testCommitSha && (
              <div className="flex items-center justify-between text-sm">
                <span className="text-red-600 dark:text-red-400 font-medium">{getStepEmoji('red')} {getStepLabel('red')}</span>
                <span className="font-mono text-xs">{progressTask.testCommitSha.substring(0, 7)}</span>
              </div>
            )}
            {progressTask.commitSha && (
              <div className="flex items-center justify-between text-sm">
                <span className="text-green-600 dark:text-green-400 font-medium">{getStepEmoji('green')} {getStepLabel('green')}</span>
                <span className="font-mono text-xs">{progressTask.commitSha.substring(0, 7)}</span>
              </div>
            )}
            {progressTask.reviews && Object.entries(progressTask.reviews).flatMap(([type, review]) => {
              const label = getStepLabel(type);
              const items: React.ReactElement[] = [];
              if (review.completedAt) {
                items.push(
                  <div key={`${type}-review`} className="flex items-center justify-between text-sm">
                    <span className="text-purple-600 dark:text-purple-400 font-medium">
                      {getStepEmoji(type)} {label}
                    </span>
                    <span className="font-mono text-xs">{formatDuration(review.startedAt, review.completedAt)}</span>
                  </div>
                );
              }
              if (review.refactorCommitSha) {
                items.push(
                  <div key={`${type}-refactor`} className="flex items-center justify-between text-sm">
                    <span className="text-blue-600 dark:text-blue-400 font-medium">
                      {getStepEmoji('refactor')} {label} Refactor
                    </span>
                    <span className="font-mono text-xs">{review.refactorCommitSha.substring(0, 7)}</span>
                  </div>
                );
              }
              return items;
            })}
          </div>
        </div>
      )}
    </div>
  );
};

const TaskDetailPanel: React.FC<TaskDetailPanelProps> = ({
  isOpen,
  onClose,
  repoId,
  planId,
  featureId,
  fixId,
  taskNumber,
  progressTask,
}) => {
  const { open, close } = useDetailsPopover();

  const handleClose = () => {
    close();
  };

  useEffect(() => {
    if (isOpen) {
      open(
        <TaskDetailContent
          repoId={repoId}
          planId={planId}
          featureId={featureId}
          fixId={fixId}
          taskNumber={taskNumber}
          progressTask={progressTask}
          onClose={handleClose}
        />,
        { width: 'w-[480px]', onClose }
      );
    } else {
      close();
    }
  }, [isOpen, repoId, planId, featureId, fixId, taskNumber, progressTask]);

  return null;
};

export default TaskDetailPanel;
