/**
 * Pipeline Normalizer
 *
 * Converts pipeline config entries from legacy string format to PipelineStep objects.
 * Accepts both formats for backwards compatibility.
 */
/** Shared adversarial step constant — use this instead of duplicating the literal */
export const ADVERSARIAL_STEP = {
    type: 'adversarial',
    agent: 'tiny-brain:adversarial-reviewer',
    label: 'Adversarial Review',
    emoji: '\u{1F608}', // 😈
    color: '#e45858', // red
};
/** Shared coverage step constant — now uses analyzer-agent wrapper */
export const CODE_COVERAGE_STEP = {
    type: 'coverage',
    agent: 'tiny-brain:analyzer-agent',
    label: 'Code Coverage',
    emoji: '\u{1F4C8}', // 📈
    color: '#4caf50', // green
    analyzer: 'coverage',
    analyzerThreshold: { min: 80 },
    mode: 'tollgate',
    runsTests: true,
};
/** TypeScript hook step — runs tsc --noEmit in pre-commit */
export const TYPESCRIPT_HOOK_STEP = {
    type: 'typescript',
    agent: 'tiny-brain:analyzer-agent',
    label: 'TypeScript',
    emoji: '\u{1F4DD}', // 📝
    color: '#3178c6', // typescript blue
    analyzer: 'typescript',
    hook: 'pre-commit',
};
/** ESLint hook step — runs eslint in pre-commit */
export const ESLINT_HOOK_STEP = {
    type: 'eslint',
    agent: 'tiny-brain:analyzer-agent',
    label: 'ESLint',
    emoji: '\u{1F9F9}', // 🧹
    color: '#4b32c3', // eslint purple
    analyzer: 'eslint',
    hook: 'pre-commit',
};
/** Default quality pipeline step types */
export const DEFAULT_QUALITY_TYPES = ['code-quality', 'coverage', 'dependency-audit', 'performance', 'security', 'testing'];
/** Known defaults for legacy string types — emoji must match capability frontmatter */
const KNOWN_DEFAULTS = {
    adversarial: { ...ADVERSARIAL_STEP },
    'typescript': { ...TYPESCRIPT_HOOK_STEP },
    'eslint': { ...ESLINT_HOOK_STEP },
    'coverage': { ...CODE_COVERAGE_STEP },
    'code-quality': {
        type: 'code-quality',
        agent: 'tiny-brain:code-quality-reviewer',
        label: 'Code Quality',
        emoji: '\u{1F50D}', // 🔍
        color: '#7c4dff', // purple
    },
    'mutation': {
        type: 'mutation',
        agent: 'tiny-brain:analyzer-agent',
        label: 'Mutation Testing',
        emoji: '\u{1F9DF}', // 🧟
        color: '#8bc34a', // lime
        analyzer: 'mutation-testing',
        runsTests: true,
    },
    'performance': {
        type: 'performance',
        agent: 'tiny-brain:performance-reviewer',
        label: 'Performance Review',
        emoji: '\u{26A1}', // ⚡
        color: '#ff9800', // orange
    },
    'security': {
        type: 'security',
        agent: 'tiny-brain:security-reviewer',
        label: 'Security Review',
        emoji: '\u{1F510}', // 🔐
        color: '#2196f3', // blue
    },
    'tdd-compliance': {
        type: 'tdd-compliance',
        agent: 'tiny-brain:tdd-compliance-reviewer',
        label: 'TDD Compliance',
        emoji: '\u{2705}', // ✅
        color: '#009688', // teal
    },
    'testing': {
        type: 'testing',
        agent: 'tiny-brain:testing-reviewer',
        label: 'Testing Review',
        emoji: '\u{1F9EA}', // 🧪
        color: '#e91e63', // pink
    },
    'dependency-audit': {
        type: 'dependency-audit',
        agent: 'tiny-brain:analyzer-agent',
        label: 'Dependency Audit',
        emoji: '\u{1F4E6}', // 📦
        color: '#795548', // brown
        analyzer: 'dependency-audit',
        analyzerThreshold: { maxSeverity: 'high' },
    },
};
/** Hash an emoji to a stable hue (0-360) for generating default colors. */
export function emojiToHue(emoji) {
    let hash = 0;
    for (let i = 0; i < emoji.length; i++) {
        hash = ((hash << 5) - hash + emoji.charCodeAt(i)) | 0;
    }
    return ((hash % 360) + 360) % 360;
}
/** Convert a hue to a hex color at fixed saturation/lightness. */
function hueToHex(hue) {
    // HSL to RGB at S=60%, L=50%
    const s = 0.6, l = 0.5;
    const c = (1 - Math.abs(2 * l - 1)) * s;
    const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
    const m = l - c / 2;
    let r = 0, g = 0, b = 0;
    if (hue < 60) {
        r = c;
        g = x;
    }
    else if (hue < 120) {
        r = x;
        g = c;
    }
    else if (hue < 180) {
        g = c;
        b = x;
    }
    else if (hue < 240) {
        g = x;
        b = c;
    }
    else if (hue < 300) {
        r = x;
        b = c;
    }
    else {
        r = c;
        b = x;
    }
    const toHex = (v) => Math.round((v + m) * 255).toString(16).padStart(2, '0');
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}
export function stringToStep(type) {
    if (KNOWN_DEFAULTS[type]) {
        return { ...KNOWN_DEFAULTS[type] };
    }
    // Generate sensible defaults for unknown types
    const label = type
        .split('-')
        .map(w => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ');
    const emoji = '\u{1F50D}';
    return {
        type,
        agent: `tiny-brain:${type}-reviewer`,
        label,
        emoji,
        color: hueToHex(emojiToHue(emoji)),
    };
}
export function isPipelineStep(entry) {
    return (typeof entry === 'object' &&
        entry !== null &&
        'type' in entry &&
        'agent' in entry &&
        'label' in entry &&
        'emoji' in entry);
}
/**
 * Normalize a pipeline config array. Accepts string[], PipelineStep[], or mixed.
 * Returns PipelineStep[] with all entries as full objects.
 *
 * For object entries with a known type, KNOWN_DEFAULTS are merged UNDER the
 * user entry. This means optional intrinsic fields the user omits
 * (`runsTests`, `analyzer`, `analyzerThreshold`) are inherited from defaults,
 * while everything the user explicitly sets wins. `analyzerThreshold` is
 * replaced whole-cloth when the user provides one (no deep merge).
 *
 * Note: `agent`, `label`, and `emoji` are required by `isPipelineStep`, so
 * they will always come from the user — defaults can never surface them.
 */
export function normalizePipeline(input) {
    if (!input)
        return [];
    return input.map(entry => {
        let step;
        if (isPipelineStep(entry)) {
            const defaults = KNOWN_DEFAULTS[entry.type];
            // Merge defaults under user entry — user wins for any field they set,
            // but intrinsic flags (runsTests, etc.) survive when user omits them.
            step = defaults ? { ...defaults, ...entry } : entry;
        }
        else {
            step = stringToStep(String(entry));
        }
        // Default maxAttempts for tollgate steps
        if (step.mode === 'tollgate' && step.maxAttempts === undefined) {
            step = { ...step, maxAttempts: 3 };
        }
        // Clamp weight (min 0) and threshold (0-100)
        if (step.weight !== undefined && step.weight < 0) {
            step = { ...step, weight: 0 };
        }
        if (step.threshold !== undefined) {
            step = { ...step, threshold: Math.max(0, Math.min(100, step.threshold)) };
        }
        // Default color from emoji hash
        if (!step.color) {
            step = { ...step, color: hueToHex(emojiToHue(step.emoji)) };
        }
        return step;
    });
}
export function getHookSteps(pipeline, hookName, options) {
    return pipeline.filter(s => {
        if (s.hook !== hookName)
            return false;
        if (options?.skipTestRunners && s.runsTests)
            return false;
        if (options?.onlyTestRunners && !s.runsTests)
            return false;
        return true;
    });
}
